mapper.select:
SELECT * FROM user_interactions
WHERE user_id = #{userId}
  AND target_type = #{targetType}
  AND target_id = #{targetId}
  AND interaction_type = #{interactionType}
LIMIT 1

SELECT * FROM user_interactions
WHERE user_id = #{userId}
  AND target_type = #{targetType}
  AND target_id IN

    #{id}

  AND interaction_type = #{interactionType}

SELECT COUNT(*) FROM user_interactions
WHERE target_type = #{targetType}
  AND target_id = #{targetId}
  AND interaction_type = #{interactionType}

SELECT target_id as targetId, COUNT(*) as likeCount
FROM user_interactions
WHERE target_type = #{targetType}
  AND target_id IN

    #{id}

  AND interaction_type = #{interactionType}
GROUP BY target_id

SELECT * FROM user_interactions
WHERE user_id = #{userId}
  AND target_type = #{targetType}
  AND interaction_type = #{interactionType}
ORDER BY created_at DESC

SELECT * FROM user_interactions
WHERE target_id = #{targetId}
  AND target_type = #{targetType}
  AND interaction_type = #{interactionType}
ORDER BY created_at DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM user_interactions
WHERE target_id = #{targetId}
  AND target_type = #{targetType}
  AND interaction_type = #{interactionType}

SELECT ui.* FROM user_interactions ui
WHERE ui.target_id = #{userId}
  AND ui.target_type = #{targetType}
  AND ui.interaction_type = #{interactionType}
  AND EXISTS (
      SELECT 1 FROM user_interactions ui2
      WHERE ui2.user_id = #{userId}
        AND ui2.target_id = ui.user_id
        AND ui2.target_type = #{targetType}
        AND ui2.interaction_type = #{interactionType}
  )
ORDER BY ui.created_at DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM user_interactions ui
WHERE ui.target_id = #{userId}
  AND ui.target_type = #{targetType}
  AND ui.interaction_type = #{interactionType}
  AND EXISTS (
      SELECT 1 FROM user_interactions ui2
      WHERE ui2.user_id = #{userId}
        AND ui2.target_id = ui.user_id
        AND ui2.target_type = #{targetType}
        AND ui2.interaction_type = #{interactionType}
  )
